//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

/// Clones share the same scores, so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    players: Arc<Mutex<HashMap<PlayerId, Arc<Mutex<i64>>>>>,
    total: Arc<Mutex<i64>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    /// Registers a player or resets an existing player's score to `score`.
    ///
    /// The total is adjusted by the difference so it always equals the sum of
    /// the individual scores, even when the same player joins twice.
    pub fn join(&self, id: PlayerId, score: i64) {
        let mut players = self.players.lock().unwrap();
        if let Some(slot) = players.get(&id).cloned() {
            let mut current = slot.lock().unwrap();
            let delta = score - *current;
            *current = score;
            drop(current);
            drop(players);
            *self.total.lock().unwrap() += delta;
            return;
        }
        players.insert(id, Arc::new(Mutex::new(score)));
        drop(players);
        *self.total.lock().unwrap() += score;
    }

    fn slot(&self, id: PlayerId) -> Arc<Mutex<i64>> {
        self.players.lock().unwrap()[&id].clone()
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let slot = self.slot(id);
        // Read, modify and write under one guard; releasing it between the
        // read and the write loses concurrent awards. Keep the total update
        // inside the same critical section so score and total stay in step.
        let mut score = slot.lock().unwrap();
        *score += points;
        *self.total.lock().unwrap() += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        if from == to {
            return;
        }
        // Always acquire the lower player id first. Two transfers in opposite
        // directions would otherwise take the two slot locks in opposite
        // orders and deadlock.
        let (first_slot, second_slot) = if from < to {
            (self.slot(from), self.slot(to))
        } else {
            (self.slot(to), self.slot(from))
        };
        let mut first = first_slot.lock().unwrap();
        let mut second = second_slot.lock().unwrap();
        if from < to {
            *first -= points;
            *second += points;
        } else {
            *second -= points;
            *first += points;
        }
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        *self.slot(id).lock().unwrap()
    }

    pub fn total(&self) -> i64 {
        *self.total.lock().unwrap()
    }
}

