mod tests {
    use super::*;
    use std::sync::Barrier;
    use std::thread;

    #[test]
    fn concurrent_awards_do_not_lose_points() {
        let board = Board::new();
        board.join(1, 0);
        let threads = 8;
        let per_thread = 10_000;
        let barrier = Arc::new(Barrier::new(threads));
        let mut handles = Vec::new();
        for _ in 0..threads {
            let board = board.clone();
            let barrier = barrier.clone();
            handles.push(thread::spawn(move || {
                barrier.wait();
                for _ in 0..per_thread {
                    board.award(1, 1);
                }
            }));
        }
        for handle in handles {
            handle.join().unwrap();
        }
        assert_eq!(board.score(1), (threads * per_thread) as i64);
        assert_eq!(board.total(), (threads * per_thread) as i64);
    }

